import { existsSync } from 'node:fs';
import path from 'node:path';
import { migrate } from 'drizzle-orm/better-sqlite3/migrator';
import { REPO_ROOT, loadConfig } from '../lib/config.js';
import { openDatabase } from './client.js';

/** Versioned SQL migrations generated by drizzle-kit (`pnpm db:generate`). Forward-only. */
export const MIGRATIONS_DIR = path.join(REPO_ROOT, 'apps/api/migrations');

const config = loadConfig();
const journal = path.join(MIGRATIONS_DIR, 'meta/_journal.json');

// Print the target so nobody migrates the production file by accident. Path only, no data.
console.log(`[db:migrate] target: ${config.DATABASE_PATH} (NODE_ENV=${config.NODE_ENV})`);

if (!existsSync(journal)) {
  console.log('[db:migrate] no migrations yet — nothing to apply.');
  process.exit(0);
}

const handle = openDatabase(config.DATABASE_PATH);
try {
  migrate(handle.db, { migrationsFolder: MIGRATIONS_DIR });
  console.log('[db:migrate] up to date.');
} finally {
  handle.close();
}
